<?php require_once 'config/auth.php'; require_admin(); $pageTitle='Categorías';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$nombre=trim($_POST['nombre']??'');if(!$nombre){flash('danger','El nombre es obligatorio.');}else{try{$pdo->prepare('INSERT INTO categoria(nombre) VALUES(?)')->execute([$nombre]);flash('success','Categoría creada.');}catch(PDOException $e){flash('danger','No se pudo crear la categoría.');}}}elseif($action==='toggle'){
$st=$pdo->prepare('SELECT estado FROM categoria WHERE id_categoria=?');$st->execute([$id]);$categoria=$st->fetch();
if(!$categoria){flash('danger','La categoría no existe.');}
elseif((int)$categoria['estado']===1){
$st=$pdo->prepare('SELECT COUNT(*) FROM producto WHERE id_categoria=? AND estado=1');$st->execute([$id]);$total=(int)$st->fetchColumn();
if($total>0){flash('danger','No se puede desactivar una categoría que tiene productos activos. Desactiva o cambia esos productos primero.');}
else{$pdo->prepare('UPDATE categoria SET estado=0 WHERE id_categoria=?')->execute([$id]);flash('success','Categoría desactivada.');}
}else{$pdo->prepare('UPDATE categoria SET estado=1 WHERE id_categoria=?')->execute([$id]);flash('success','Categoría activada.');}}redirect('categorias.php');}
$rows=$pdo->query('SELECT c.*,COUNT(p.id_producto) productos FROM categoria c LEFT JOIN producto p ON p.id_categoria=c.id_categoria GROUP BY c.id_categoria ORDER BY c.estado DESC,c.nombre')->fetchAll();require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">ADMINISTRACIÓN</span><h1>Categorías</h1><p>Organiza los productos por categorías.</p></div></div><div class="two-col"><section class="panel"><h2>Nueva categoría</h2><form method="post" class="form"><input type="hidden" name="action" value="save"><label>Nombre<input name="nombre" maxlength="100" required></label><button class="btn primary">Crear categoría</button></form></section><section class="panel"><h2>Listado</h2><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Productos</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nombre'])?></b></td><td><?=e((string)$r['productos'])?></td><td><?=$r['estado']?'<span class="badge success">Activa</span>':'<span class="badge">Inactiva</span>'?></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id_categoria']?>"><button class="link-btn" data-confirm="¿Cambiar el estado?">Cambiar</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require 'partials/footer.php'; ?>
